WITH valid_subscriptions AS (SELECT * FROM subscriptions WHERE plan NOT IN ('enterprise', 'premium', 'basic')), customer_id_summary AS (SELECT customer_id, status, SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END) AS standard_count FROM valid_subscriptions GROUP BY customer_id, status) SELECT customer_id, status, standard_count FROM customer_id_summary WHERE standard_count >= 49 ORDER BY standard_count DESC, status, customer_id LIMIT 5;
